function chooseTransport(req) {
  if (req.needsRealtimeUpstream) return 'WebSocket';
  if (req.serverOnlyStream) return 'SSE';
  if (req.lowFrequency) return 'short-polling';
  if (req.upgradeBlocked || req.legacyClient) return 'long-polling';
  return 'SSE';
}

function parseSSE(stream) {
  return stream.trim().split(/\n\n/).filter(Boolean).map(block => {
    const event = { type: 'message', id: '', data: [] };
    for (const line of block.split(/\n/)) {
      if (line.startsWith(':')) continue; // heartbeat/comment line
      const colon = line.indexOf(':');
      const field = colon === -1 ? line : line.slice(0, colon);
      const value = colon === -1 ? '' : line.slice(colon + 1).trimStart();
      if (field === 'event') event.type = value;
      if (field === 'id') event.id = value;
      if (field === 'data') event.data.push(value);
    }
    if (event.data.length === 0 && event.id === '' && event.type === 'message') return null;
    return { ...event, data: event.data.join('\n') };
  }).filter(Boolean);
}

function wsReconnectDelay(attempt, random01 = 0.5) {
  const base = Math.min(30000, 1000 * 2 ** attempt);
  return Math.round(base * (0.8 + random01 * 0.4));
}

const cases = [
  { name: 'IM chat', needsRealtimeUpstream: true },
  { name: 'LLM token stream', serverOnlyStream: true },
  { name: 'daily job status', lowFrequency: true },
  { name: 'legacy proxy fallback', upgradeBlocked: true }
];
for (const req of cases) {
  console.log(req.name, '=>', chooseTransport(req));
}

const sse = ':heartbeat\n\nid: 42\nevent: token\ndata: {"delta":"hello"}\n\nid: 43\ndata: [DONE]\n\n';
console.log('SSE events:', parseSSE(sse));
console.log('WS reconnect delays:', [0, 1, 2, 3, 4].map(i => wsReconnectDelay(i, 0.25)));
